class Solution:
    def numberOfSpecialChars(self, word: str) -> int:
        lowers = set(c for c in word if c.islower())
        uppers = set(c.lower() for c in word if c.isupper())
        return len(lowers & uppers)

class Solution {
public:
    int numberOfSpecialChars(string word) {
        vector<bool> lower(26, false), upper(26, false);
        for (char c : word) {
            if (islower(c)) lower[c - 'a'] = true;
            else if (isupper(c)) upper[c - 'A'] = true;
        }
        int ans = 0;
        for (int i = 0; i < 26; ++i) {
            if (lower[i] && upper[i]) ans++;
        }
        return ans;
    }
};

class Solution {
    public int numberOfSpecialChars(String word) {
        boolean[] lower = new boolean[26];
        boolean[] upper = new boolean[26];
        for (int i = 0; i < word.length(); i++) {
            char c = word.charAt(i);
            if (Character.isLowerCase(c)) lower[c - 'a'] = true;
            else if (Character.isUpperCase(c)) upper[c - 'A'] = true;
        }
        int ans = 0;
        for (int i = 0; i < 26; i++) {
            if (lower[i] && upper[i]) ans++;
        }
        return ans;
    }
}

var numberOfSpecialChars = function(word) {
    const lower = new Array(26).fill(false);
    const upper = new Array(26).fill(false);
    for (let i = 0; i < word.length; i++) {
        const code = word.charCodeAt(i);
        if (code >= 97 && code <= 122) lower[code - 97] = true;
        else if (code >= 65 && code <= 90) upper[code - 65] = true;
    }
    let ans = 0;
    for (let i = 0; i < 26; i++) {
        if (lower[i] && upper[i]) ans++;
    }
    return ans;
};
